import { Router, Request, Response, NextFunction } from "express";
import { OrderService, OrderNotFoundError, InvalidOrderStateError } from "./orderService";
import { OrderRepository } from "./orderRepository";

export function orderRoutes(service: OrderService, orders: OrderRepository): Router {
  const router = Router();

  router.post("/orders", async (req: Request, res: Response, next: NextFunction) => {
    try {
      const { customerId, lines } = req.body;
      if (!customerId || !Array.isArray(lines) || lines.length === 0) {
        return res.status(400).json({ error: "customerId and lines are required" });
      }
      const order = await service.placeOrder(customerId, lines);
      res.status(201).json(order);
    } catch (err) {
      next(err);
    }
  });

  router.get("/orders/:id", async (req: Request, res: Response, next: NextFunction) => {
    try {
      const order = await service.getOrder(req.params.id);
      res.json(order);
    } catch (err) {
      next(err);
    }
  });

  router.post("/orders/:id/cancel", async (req: Request, res: Response, next: NextFunction) => {
    try {
      const order = await orders.findById(req.params.id);
      if (!order) return res.status(404).json({ error: "order not found" });
      if (order.status !== "pending" && order.status !== "paid") {
        return res.status(409).json({ error: `cannot cancel order in status ${order.status}` });
      }
      await orders.updateStatus(order.id, "cancelled");
      res.json({ ...order, status: "cancelled" });
    } catch (err) {
      next(err);
    }
  });

  router.use((err: unknown, _req: Request, res: Response, next: NextFunction) => {
    if (err instanceof OrderNotFoundError) return res.status(404).json({ error: err.message });
    if (err instanceof InvalidOrderStateError) return res.status(409).json({ error: err.message });
    next(err);
  });

  return router;
}

import { OrderRepository, Order, OrderLine } from "./orderRepository";
import { InventoryRepository } from "./inventoryRepository";
import { Db } from "./db";

export class OrderNotFoundError extends Error {}
export class InvalidOrderStateError extends Error {}
export class OutOfStockError extends Error {}

const CANCELLABLE = new Set(["pending", "paid"]);

export class OrderService {
  constructor(
    private readonly db: Db,
    private readonly orders: OrderRepository,
    private readonly inventory: InventoryRepository,
  ) {}

  async placeOrder(customerId: string, lines: OrderLine[]): Promise<Order> {
    return this.db.transaction(async (tx) => {
      for (const line of lines) {
        const reserved = await this.inventory.reserve(tx, line.sku, line.quantity);
        if (!reserved) throw new OutOfStockError(`insufficient stock for ${line.sku}`);
      }
      return this.orders.insert(tx, { customerId, lines, status: "pending" });
    });
  }

  async getOrder(id: string): Promise<Order> {
    const order = await this.orders.findById(id);
    if (!order) throw new OrderNotFoundError(`order ${id} not found`);
    return order;
  }

  async cancelOrder(id: string): Promise<Order> {
    return this.db.transaction(async (tx) => {
      const order = await this.orders.findByIdForUpdate(tx, id);
      if (!order) throw new OrderNotFoundError(`order ${id} not found`);
      if (!CANCELLABLE.has(order.status)) {
        throw new InvalidOrderStateError(`cannot cancel order in status ${order.status}`);
      }
      for (const line of order.lines) {
        await this.inventory.release(tx, line.sku, line.quantity);
      }
      await this.orders.updateStatus(order.id, "cancelled", tx);
      return { ...order, status: "cancelled" };
    });
  }
}

import { Db, Tx } from "./db";

export type OrderStatus = "pending" | "paid" | "shipped" | "cancelled";
export interface OrderLine { sku: string; quantity: number; }
export interface Order { id: string; customerId: string; lines: OrderLine[]; status: OrderStatus; }

export class OrderRepository {
  constructor(private readonly db: Db) {}

  async findById(id: string): Promise<Order | null> {
    const rows = await this.db.query("SELECT id, customer_id, lines, status FROM orders WHERE id = $1", [id]);
    return rows[0] ? this.toOrder(rows[0]) : null;
  }

  async findByIdForUpdate(tx: Tx, id: string): Promise<Order | null> {
    const rows = await tx.query("SELECT id, customer_id, lines, status FROM orders WHERE id = $1 FOR UPDATE", [id]);
    return rows[0] ? this.toOrder(rows[0]) : null;
  }

  async insert(tx: Tx, o: Omit<Order, "id">): Promise<Order> {
    const rows = await tx.query(
      "INSERT INTO orders (customer_id, lines, status) VALUES ($1, $2, $3) RETURNING id, customer_id, lines, status",
      [o.customerId, JSON.stringify(o.lines), o.status],
    );
    return this.toOrder(rows[0]);
  }

  async updateStatus(id: string, status: OrderStatus, tx?: Tx): Promise<void> {
    await (tx ?? this.db).query("UPDATE orders SET status = $1 WHERE id = $2", [status, id]);
  }

  private toOrder(row: any): Order {
    return { id: row.id, customerId: row.customer_id, lines: row.lines, status: row.status };
  }
}
